#!/usr/bin/env python3
"""A tiny todo-list CLI, persisted as a JSON file in the current directory.

See SPEC.md for the full behavioural specification.
"""

import json
import sys
from pathlib import Path

STORE_FILENAME = "todo.json"


def store_path():
    return Path(STORE_FILENAME)


def load_store():
    path = store_path()
    if not path.exists():
        return []
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def save_store(items):
    with store_path().open("w", encoding="utf-8") as f:
        json.dump(items, f, indent=2)


def usage_error(message):
    print(f"Error: {message}", file=sys.stderr)
    sys.exit(2)


def cmd_add(args):
    if not args:
        usage_error("todo add: the following argument is required: <text>")
    text = " ".join(args)
    if text.strip() == "":
        usage_error("todo add: <text> must not be empty")

    items = load_store()
    new_id = max((item["id"] for item in items), default=0) + 1
    items.append({"id": new_id, "text": text, "done": False})
    save_store(items)
    print(f"Added todo {new_id}: {text}")


def cmd_list(args):
    if args:
        usage_error("todo list: unrecognized arguments: " + " ".join(args))

    items = load_store()
    if not items:
        print("No todos found.")
        return
    for item in sorted(items, key=lambda i: i["id"]):
        marker = "x" if item["done"] else " "
        print(f"[{marker}] {item['id']} {item['text']}")


def cmd_done(args):
    if len(args) != 1:
        usage_error("todo done: the following argument is required: <id>")
    try:
        target_id = int(args[0])
    except ValueError:
        usage_error(f"todo done: invalid int value: {args[0]!r}")

    items = load_store()
    found = None
    for item in items:
        if item["id"] == target_id:
            found = item
            break

    if found is None:
        print(f"Error: no todo with id {target_id}", file=sys.stderr)
        sys.exit(1)

    found["done"] = True
    save_store(items)
    print(f"Marked todo {target_id} as done.")


def main():
    argv = sys.argv[1:]
    if not argv:
        usage_error("usage: todo <add|list|done> [args...]")

    subcommand, rest = argv[0], argv[1:]

    if subcommand == "add":
        cmd_add(rest)
    elif subcommand == "list":
        cmd_list(rest)
    elif subcommand == "done":
        cmd_done(rest)
    else:
        usage_error(f"unknown subcommand: {subcommand!r}")


if __name__ == "__main__":
    main()

